5	use App\Mail\StaffBroadcastMail;
6	use App\Models\Core\Notifications\EmailSubscription;
7	use App\Models\Core\Notifications\Notification;
8	use Illuminate\Bus\Queueable;
9	use Illuminate\Contracts\Queue\ShouldQueue;
10	use Illuminate\Foundation\Bus\Dispatchable;
11	use Illuminate\Queue\InteractsWithQueue;
12	use Illuminate\Queue\SerializesModels;
13	use Illuminate\Support\Facades\Mail;
14	
15	// V2: Sends individual staff broadcast email, respecting unsubscribe preferences and subscriber status.
16	class SendStaffBroadcastEmailToSubscriberJob implements ShouldQueue
17	{
18	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
19	
20	    public int $tries = 3;
21	
22	    public function __construct(
23	        public string $notificationId,
24	        public string $subscriptionId
25	    ) {}
26	
27	    public function handle(): void
28	    {
29	        $notification = Notification::query()->find($this->notificationId);
30	        if (! $notification) {
31	            return;
32	        }
33	
34	        $sub = EmailSubscription::query()->find($this->subscriptionId);
35	        if (! $sub) {
36	            return;
37	        }
38	
39	        // Respect unsubscribes that happened after the broadcast was queued
40	        if ($sub->status !== 'subscribed') {
41	            return;
42	        }
43	
44	        $unsubscribeUrl = route('public.unsubscribe', ['token' => $sub->unsubscribe_token]);
45	
46	        Mail::to($sub->email)->send(
47	            new StaffBroadcastMail($notification, $unsubscribeUrl)
48	        );
49	    }
50	}
