3	namespace App\Jobs\Notifications;
4	
5	use App\Models\Core\Professional\Professional;
6	use Illuminate\Bus\Queueable;
7	use Illuminate\Contracts\Queue\ShouldQueue;
8	use Illuminate\Foundation\Bus\Dispatchable;
9	use Illuminate\Queue\InteractsWithQueue;
10	use Illuminate\Queue\SerializesModels;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	
14	// V2: Fans out brand status change notifications to all connected affiliates.
15	// Only fires for affiliate-facing status transitions (live, building, systems_down).
16	// preview transitions are internal wizard state and don't notify affiliates.
17	// Dispatches one SendBrandStatusNotificationJob per affiliate so failures isolate
18	// and retry independently.
19	class FanOutBrandStatusNotificationJob implements ShouldQueue
20	{
21	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
22	
23	    public int $tries = 3;
24	
25	    public function __construct(
26	        public readonly string $brandProfessionalId,
27	        public readonly string $brandStatus, // BrandStatus::ReadyForAffiliates->value | BrandStatus::Onboarding->value | BrandStatus::SystemsDown->value
28	    ) {
29	        $this->onQueue('notifications');
30	    }
31	
32	    public function handle(): void
33	    {
34	        $brand = Professional::find($this->brandProfessionalId);
35	
36	        if (! $brand) {
37	            Log::warning('FanOutBrandStatusNotificationJob: brand not found, skipping fan-out', [
38	                'brand_professional_id' => $this->brandProfessionalId,
39	            ]);
40	
41	            return;
42	        }
43	
44	        $yearWeek = now()->format('o-W');
45	        $brandName = (string) ($brand->display_name ?: $brand->handle ?: 'Brand');
46	
47	        DB::table('brand.brand_partner_links')
48	            ->where('brand_professional_id', $this->brandProfessionalId)
49	            ->chunkById(500, function ($rows) use ($brandName, $yearWeek) {
50	                foreach ($rows as $row) {
51	                    SendBrandStatusNotificationJob::dispatch(
52	                        affiliateProfessionalId: $row->affiliate_professional_id,
53	                        brandProfessionalId: $this->brandProfessionalId,
54	                        brandName: $brandName,
55	                        brandStatus: $this->brandStatus,
56	                        yearWeek: $yearWeek,
57	                    );
58	                }
59	            });
60	    }
61	
62	    public function failed(\Throwable $e): void
63	    {
64	        Log::error('FanOutBrandStatusNotificationJob failed', [
65	            'brand_professional_id' => $this->brandProfessionalId,
66	            'brand_status' => $this->brandStatus,
67	            'message' => $e->getMessage(),
68	        ]);
69	    }
70	}
