3	namespace App\Jobs\Notifications;
4	
5	use App\Models\Core\Notifications\Notification;
6	use App\Services\Notifications\NotificationPublisher;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\DB;
13	use Illuminate\Support\Facades\Log;
14	use Illuminate\Support\Facades\Mail;
15	
16	// V2: Sends category-specific transactional emails (invites, commissions, payouts). Respects feature flags and user email preferences.
17	class SendTransactionalNotificationEmailJob implements ShouldQueue
18	{
19	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
20	
21	    public int $tries = 3;
22	
23	    public array $backoff = [30, 120, 300];
24	
25	    public function __construct(
26	        public readonly string $notificationId,
27	        public readonly string $category,
28	        public readonly string $professionalId,
29	    ) {
30	        $this->onQueue('notifications');
31	    }
32	
33	    public function handle(): void
34	    {
35	        if (! config('sidest.notifications.email_enabled', false)) {
36	            Log::debug('Notification email skipped: feature disabled', [
37	                'category' => $this->category,
38	            ]);
39	
40	            return;
41	        }
42	
43	        // Early-exit if this category has no mailable (in-app-only or unregistered).
44	        // Avoids unnecessary DB queries when there's nothing to send.
45	        $class = config("sidest.notifications.mailables.{$this->category}");
46	        if (! is_string($class) || ! class_exists($class)) {
47	            Log::debug('Notification email skipped: category has no mailable', [
48	                'category' => $this->category,
49	            ]);
50	
51	            return;
52	        }
53	
54	        if (! NotificationPublisher::resolveEmailEnabled($this->professionalId, $this->category)) {
55	            Log::debug('Notification email skipped: user preference disabled', [
56	                'category' => $this->category,
57	                'professional_id' => $this->professionalId,
58	            ]);
59	
60	            return;
61	        }
62	
63	        $notification = Notification::query()->find($this->notificationId);
64	        if (! $notification instanceof Notification) {
65	            Log::warning('Notification email skipped: notification not found', [
66	                'notification_id' => $this->notificationId,
67	            ]);
68	
69	            return;
70	        }
71	
72	        $email = DB::table('core.professionals')
73	            ->where('id', $this->professionalId)
74	            ->whereNull('deleted_at')
75	            ->value('primary_email');
76	
77	        if (! $email) {
78	            Log::warning('Notification email skipped: no email on record', [
79	                'professional_id' => $this->professionalId,
80	            ]);
81	
82	            return;
83	        }
84	
85	        $mailable = $this->buildMailable($notification, $class);
86	        if ($mailable === null) {
87	            Log::warning('Notification email skipped: mailable instantiation failed', [
88	                'category' => $this->category,
89	                'class' => $class,
90	            ]);
91	
92	            return;
93	        }
94	
95	        Mail::to($email)->send($mailable);
96	    }
97	
98	    public function failed(\Throwable $e): void
99	    {
100	        Log::error('Transactional notification email failed', [
101	            'notification_id' => $this->notificationId,
102	            'category' => $this->category,
103	            'professional_id' => $this->professionalId,
104	            'message' => $e->getMessage(),
105	        ]);
106	    }
107	
108	    private function buildMailable(Notification $notification, string $class): ?\Illuminate\Mail\Mailable
109	    {
110	        $mailable = new $class($notification);
111	
112	        if (! $mailable instanceof \Illuminate\Mail\Mailable) {
113	            return null;
114	        }
115	
116	        return $mailable;
117	    }
118	}
