5	use App\Services\Notifications\NotificationPublisher;
6	use Illuminate\Bus\Queueable;
7	use Illuminate\Contracts\Queue\ShouldQueue;
8	use Illuminate\Foundation\Bus\Dispatchable;
9	use Illuminate\Queue\InteractsWithQueue;
10	use Illuminate\Queue\SerializesModels;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	
14	// V2: Marks expired affiliate invites and publishes expiry notifications to brand managers.
15	class InviteExpirySweepJob implements ShouldQueue
16	{
17	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
18	
19	    public int $tries = 1;
20	
21	    public int $timeout = 120;
22	
23	    public function __construct()
24	    {
25	        $this->onQueue('notifications');
26	    }
27	
28	    public function handle(NotificationPublisher $publisher): void
29	    {
30	        $now = now();
31	
32	        $expired = DB::table('brand.brand_affiliate_invites')
33	            ->where('status', 'pending')
34	            ->where('expires_at', '<', $now)
35	            ->get(['id', 'brand_professional_id', 'email', 'first_name']);
36	
37	        foreach ($expired as $invite) {
38	            try {
39	                DB::table('brand.brand_affiliate_invites')
40	                    ->where('id', $invite->id)
41	                    ->where('status', 'pending') // guard against concurrent updates
42	                    ->update(['status' => 'expired', 'updated_at' => $now]);
43	
44	                $brandId = trim((string) ($invite->brand_professional_id ?? ''));
45	                if ($brandId === '') {
46	                    continue;
47	                }
48	
49	                $label = trim((string) ($invite->first_name ?? ''));
50	                if ($label === '') {
51	                    $label = trim((string) ($invite->email ?? ''));
52	                }
53	                if ($label === '') {
54	                    $label = 'An invitee';
55	                }
56	
57	                $publisher->publish(
58	                    professionalId: $brandId,
59	                    frontendType: 'Warning',
60	                    category: 'invites',
61	                    title: 'Invite expired',
62	                    body: "Your invite to {$label} has expired.",
63	                    dedupeKey: "invite.expired.{$invite->id}",
64	                    ctaUrl: '/account/affiliates',
65	                    retentionConfigKey: 'invite',
66	                );
67	            } catch (\Throwable $e) {
68	                Log::warning('InviteExpirySweepJob failed for invite', [
69	                    'invite_id' => $invite->id,
70	                    'message' => $e->getMessage(),
71	                ]);
72	            }
73	        }
74	    }
75	
76	    public function failed(\Throwable $e): void
77	    {
78	        Log::error('Invite expiry sweep job failed', [
79	            'message' => $e->getMessage(),
80	        ]);
81	    }
82	}
