26	// V2: Generates WebP variants for uploaded images. Updates SiteMedia state (pending → ready/failed). Queue: images.
27	class ProcessImageVariantsJob implements ShouldQueue
28	{
29	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
30	
31	    public int $tries = 3;
32	
33	    public int $backoff = 30;
34	
35	    /**
36	     * @param  string  $originalPath  Path of the original on the media disk.
37	     * @param  string  $imageId  UUID of the SiteMedia row.
38	     * @param  string  $basePath  Directory prefix for variant storage.
39	     */
40	    public function __construct(
41	        public readonly string $originalPath,
42	        public readonly string $imageId,
43	        public readonly string $basePath,
44	    ) {
45	        $this->onQueue('images');
46	    }
47	
48	    public function handle(ImageVariantService $service): void
49	    {
50	        Log::info('ProcessImageVariantsJob: starting', [
51	            'image_id' => $this->imageId,
52	            'original_path' => $this->originalPath,
