88	        // Get brand settings and platform fallback for server-side rate resolution.
89	        $brandSettings = BrandStoreSettings::where('professional_id', $this->brandProfessionalId)->first();
90	        $platformDefault = (float) config('sidest.store.default_commission_rate', 15);
91	
92	        // Collect distinct product GIDs from the order's line items. Shopify
93	        // sends a numeric product_id on the REST webhook payload; convert to GID
94	        // shape so we can query the Admin API (which only accepts GIDs via nodes()).
95	        $productGids = [];
96	        foreach ($lineItems as $li) {
97	            if (! is_array($li)) {
98	                continue;
99	            }
100	            $productId = (string) Arr::get($li, 'product_id', '');
101	            // Validate numeric-only before embedding in GID to prevent injection via tampered payload.
102	            if ($productId !== '' && preg_match('/^\d+$/', $productId)) {
103	                $productGids[] = "gid://shopify/Product/{$productId}";
104	            }
105	        }
106	        $productGids = array_values(array_unique($productGids));
107	
108	        // Fetch commission_override metafield for each product in ONE Admin API
109	        // call. Buyer-set sidest_commission_rate line attributes are NOT used for
110	        // calculation — they're writable by the buyer via the Storefront Cart API
111	        // and therefore untrusted. We resolve the rate ourselves using the same
112	        // precedence the Hydrogen storefront applies.
113	        $integration = ProfessionalIntegration::query()
114	            ->where('professional_id', $this->brandProfessionalId)
115	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
116	            ->first();
117	
118	        // Validate order currency against shop_currency stored in integration metadata.
119	        // Mismatches (e.g. a multi-currency store misconfiguration) mean commission math
120	        // would be in the wrong unit — skip and log rather than create wrong ledger entries.
121	        $shopCurrency = strtoupper(trim((string) Arr::get($integration?->provider_metadata ?? [], 'shop_currency', '')));
122	        if ($shopCurrency !== '' && $shopCurrency !== $currency) {
123	            Log::warning('Shopify order webhook: currency mismatch, skipping commission', [
124	                'order_id' => $orderId,
125	                'brand_professional_id' => $this->brandProfessionalId,
126	                'order_currency' => $currency,
127	                'shop_currency' => $shopCurrency,
128	            ]);
129	
130	            return;
131	        }
132	
133	        $overrideMap = ($integration && ! empty($productGids))
134	            ? $catalogService->fetchCommissionOverridesForProducts($integration, $productGids)
135	            : [];
136	
137	        // Phase 1: build candidates without touching the DB
138	        $candidates = [];
139	        foreach ($lineItems as $lineItem) {
140	            if (! is_array($lineItem)) {
141	                continue;
142	            }
143	
144	            $lineItemId = (string) Arr::get($lineItem, 'id', '');
145	            $unitPrice = (float) Arr::get($lineItem, 'price', 0);
146	            $quantity = (int) Arr::get($lineItem, 'quantity', 1);
147	
148	            if ($lineItemId === '' || $unitPrice <= 0 || $quantity <= 0) {
149	                continue;
150	            }
151	
152	            // Commission base = what the customer actually paid for this line
153	            // (post-discount). Shopify's orders/paid webhook line_items shape:
154	            //   price             — pre-discount unit price
155	            //   quantity          — units in the line
156	            //   total_discount    — sum of every discount allocation applied to this line
157	            //                       (Side St Price Function discount included)
158	            //   discount_allocations[] — per-allocation breakdown (not needed here,
159	            //       but worth knowing if we ever need to differentiate our function
160	            //       from a manually-applied code on the same line).
161	            //
162	            // Using post-discount line total keeps commission aligned with the
163	            // brand's actual revenue on the sale — a 20% Side St Price discount
164	            // means the brand took home 20% less, and the affiliate's commission
165	            // on that line is 20% smaller too at the same commission rate.
166	            $lineTotalPreDiscount = $unitPrice * $quantity;
167	            $totalDiscount = (float) Arr::get($lineItem, 'total_discount', 0);
168	            $lineTotal = max(0.0, $lineTotalPreDiscount - $totalDiscount);
169	
170	            if ($lineTotal <= 0) {
171	                // Line fully discounted (100% off, comp, etc.) — nothing to
172	                // accrue. Skip rather than emit a zero-cent entry.
173	                continue;
174	            }
175	
176	            $productGid = ($productIdStr = (string) Arr::get($lineItem, 'product_id', '')) !== ''
177	                ? "gid://shopify/Product/{$productIdStr}"
178	                : '';
179	
180	            [$commissionRate, $rateSource] = $this->resolveCommissionRate(
181	                $productGid,
182	                $overrideMap,
183	                $brandSettings,
184	                $platformDefault,
185	            );
186	
187	            $commissionAmountCents = (int) round($lineTotal * ($commissionRate / 100) * 100);
188	
189	            if ($commissionAmountCents <= 0) {
190	                continue;
191	            }
192	
193	            // Audit trail: the buyer-submitted rate (may be empty or inflated).
194	            // Recorded verbatim so post-hoc investigations can detect tampering.
195	            $submittedRate = $this->extractSubmittedRate($lineItem);
196	
197	            $candidates[] = [
198	                'idempotency_key' => "shopify_order_{$orderId}_line_{$lineItemId}",
199	                'data' => [
200	                    'shopify_order_id' => $orderId,
201	                    'brand_professional_id' => $this->brandProfessionalId,
202	                    'affiliate_professional_id' => (string) $affiliate->id,
203	                    'entry_type' => 'accrual',
204	                    'status' => 'approved',
205	                    'amount_cents' => $commissionAmountCents,
206	                    'currency_code' => $currency,
207	                    'commission_rate' => $commissionRate,
208	                    'rate_source' => $rateSource,
209	                    'idempotency_key' => "shopify_order_{$orderId}_line_{$lineItemId}",
210	                    'calculation_metadata' => [
211	                        'order_id' => $orderId,
212	                        'line_item_id' => $lineItemId,
213	                        'product_id' => (string) Arr::get($lineItem, 'product_id', ''),
214	                        // Variant powers the per-variant breakdown on the
215	                        // Shopify-admin product analytics block. Stored as the
216	                        // numeric Shopify ID; we promote to a GID at read time.
217	                        'variant_id' => (string) Arr::get($lineItem, 'variant_id', ''),
218	                        'variant_title' => (string) Arr::get($lineItem, 'variant_title', ''),
219	                        // Captured here because Shopify only populates `title` on
220	                        // the order/line payload — fetching it later would need an
221	                        // Admin API roundtrip per row. Powers the "Top Products"
222	                        // analytics widget.
223	                        'product_title' => (string) Arr::get($lineItem, 'title', ''),
224	                        // Keep both for audit: pre-discount line price (what the
225	                        // Shopify sticker was) plus the discount applied by
226	                        // any function/code, plus the post-discount figure we
227	                        // computed commission off.
228	                        'unit_price' => $unitPrice,
229	                        'line_price_pre_discount' => $lineTotalPreDiscount,
230	                        'total_discount' => $totalDiscount,
231	                        'line_price_post_discount' => $lineTotal,
232	                        'quantity' => $quantity,
233	                        'affiliate_slug' => $affiliateSlug,
234	                        'submitted_rate' => $submittedRate,
235	                    ],
236	                    'occurred_at' => $occurredAt,
237	                ],
238	            ];
239	        }
240	
241	        // Phase 2: pre-filter existing idempotency keys (one query), then bulk-insert in one transaction.
242	        // Pre-filtering avoids a 23505 unique violation inside the transaction — PostgreSQL aborts the
243	        // entire transaction on constraint violations, so we can't catch-and-continue inside DB::transaction().
244	        $entriesCreated = 0;
245	        if (! empty($candidates)) {
246	            $candidateKeys = array_column($candidates, 'idempotency_key');
247	            $existingKeys = CommissionLedgerEntry::whereIn('idempotency_key', $candidateKeys)
248	                ->pluck('idempotency_key')
249	                ->flip()
250	                ->all();
251	
252	            $newEntries = array_filter($candidates, fn ($c) => ! isset($existingKeys[$c['idempotency_key']]));
253	
254	            DB::transaction(function () use ($newEntries, $affiliate, &$entriesCreated): void {
255	                foreach ($newEntries as $entry) {
256	                    // Preload the relation before save so the observer's notifyBrandSale()
257	                    // can access affiliateProfessional->display_name without a lazy query.
258	                    // The pre-set survives the observer's afterCommit dispatch — Laravel
259	                    // keeps object identity (no clone) for synchronous post-commit callbacks.
260	                    $row = (new CommissionLedgerEntry)->forceFill($entry['data']);
261	                    $row->setRelation('affiliateProfessional', $affiliate);
262	                    $row->save();
263	                    $entriesCreated++;
264	                }
265	            });
266	        }
267	
268	        // Capture the buyer as an affiliate contact (Beta 3 — Contacts — Automatic Customer Capture).
269	        // Non-blocking: any failure inside the service is logged and swallowed so it can never
270	        // fail commission processing above.
271	        $this->captureAffiliateContact($contactCapture, (string) $affiliate->id, $noteAttributes, $orderId);
272	
273	        // Rebuild commerce daily aggregates so dashboards and weekly notifications
274	        // reflect this order. Non-blocking — queued on the analytics worker.
275	        if ($entriesCreated > 0) {
276	            \App\Jobs\Analytics\RebuildCommerceDailyAggregatesJob::dispatch(
277	                $this->brandProfessionalId,
278	                (string) $affiliate->id,
279	                Carbon::parse($occurredAt)->toDateString()
280	            );
281	            \App\Jobs\Analytics\RebuildCommerceHourlyAggregatesJob::dispatch(
282	                $this->brandProfessionalId,
283	                (string) $affiliate->id,
284	                Carbon::parse($occurredAt)->utc()->startOfHour()->toIso8601String()
285	            );
286	        }
287	
288	        Log::info('Shopify order webhook processed', [
289	            'order_id' => $orderId,
290	            'brand_professional_id' => $this->brandProfessionalId,
291	            'affiliate_id' => (string) $affiliate->id,
292	            'entries_created' => $entriesCreated,
293	        ]);
294	    }
295	
296	    /**
297	     * Upsert the buyer into the affiliate's contacts list and, if the cart
298	     * carried a truthy `sidest_marketing_opt_in` attribute, add them to the
299	     * affiliate's marketing subscribers.
300	     *
301	     * Name resolution priority (matches the commit message): try
302	     * billing_address.name first (Shopify populates this with the full name
303	     * as entered at checkout), then fall back to customer.first_name +
304	     * customer.last_name from the Shopify customer record.
305	     *
306	     * @param  array<int, array<string, mixed>>|mixed  $noteAttributes
307	     */
308	    private function captureAffiliateContact(
309	        ContactCaptureService $contactCapture,
310	        string $affiliateId,
311	        mixed $noteAttributes,
312	        string $orderId,
313	    ): void {
314	        $customer = Arr::get($this->orderPayload, 'customer', []);
315	        $billingAddress = Arr::get($this->orderPayload, 'billing_address', []);
316	
317	        $email = trim((string) Arr::get($customer, 'email', ''));
318	        if ($email === '') {
319	            // Shopify guest checkouts or POS orders without a customer — nothing to capture.
320	            return;
321	        }
322	
323	        // Name: prefer billing_address.name, then fall back to customer first/last.
324	        $billingName = trim((string) Arr::get($billingAddress, 'name', ''));
325	        $firstName = trim((string) Arr::get($customer, 'first_name', ''));
326	        $lastName = trim((string) Arr::get($customer, 'last_name', ''));
327	        $fullName = $billingName !== '' ? $billingName : trim($firstName.' '.$lastName);
328	        $fullName = $fullName !== '' ? $fullName : null;
329	
330	        $marketingConsent = $this->parseMarketingOptInAttribute($noteAttributes);
331	
332	        // ContactCaptureService normalizes phone/full_name null-or-empty — we
333	        // can pass raw values through without pre-guarding.
334	        $contactCapture->captureContact($affiliateId, [
335	            'email' => $email,
336	            'full_name' => $fullName,
337	            'phone' => (string) Arr::get($billingAddress, 'phone', ''),
338	            'source' => 'shopify_order',
339	            'external_id' => $orderId !== '' ? $orderId : null,
340	            // Only override the service default when the shopper EXPLICITLY opted out.
341	            // Missing attribute -> null -> service default (true). Explicit "true" is
342	            // also null here because captureMarketingSubscription() handles it below.
343	            'marketing_opt_in' => $marketingConsent === false ? false : null,
344	        ]);
345	
346	        // Truthy consent -> add them to the marketing list. Missing/falsy: the
347	        // contact is still captured above, just not subscribed for email blasts.
348	        if ($marketingConsent === true) {
349	            $contactCapture->captureMarketingSubscription(
350	                $affiliateId,
351	                $email,
352	                $fullName,
353	                'shopify_order',
354	            );
355	        }
356	    }
357	
358	    /**
359	     * Parse the `sidest_marketing_opt_in` cart attribute into an explicit
360	     * tri-state: true (explicit opt-in), false (explicit opt-out), or null
361	     * (attribute missing / unrecognized value — let the schema default apply).
362	     *
363	     * Hydrogen is the only documented producer of this attribute. Recognized
364	     * values (case-insensitive):
365	     *   truthy:  'true' | '1' | 'yes'
366	     *   falsy:   'false' | '0' | 'no'
367	     *
368	     * Any other string is treated as "missing" so a typo doesn't silently
369	     * flip consent to false.
370	     *
371	     * @param  array<int, array<string, mixed>>|mixed  $noteAttributes
372	     */
373	    private function parseMarketingOptInAttribute(mixed $noteAttributes): ?bool
374	    {
375	        $raw = strtolower($this->extractCartAttribute($noteAttributes, 'sidest_marketing_opt_in'));
376	        if ($raw === '') {
377	            return null;
378	        }
379	        if (in_array($raw, ['true', '1', 'yes'], true)) {
380	            return true;
381	        }
382	        if (in_array($raw, ['false', '0', 'no'], true)) {
383	            return false;
384	        }
385	
386	        return null;
387	    }
388	
389	    /**
390	     * Extract a value from Shopify note_attributes (cart-level attributes).
391	     */
392	    private function extractCartAttribute(mixed $noteAttributes, string $key): string
393	    {
394	        if (! is_array($noteAttributes)) {
395	            return '';
396	        }
397	
398	        foreach ($noteAttributes as $attr) {
399	            if (is_array($attr) && strtolower(trim((string) ($attr['name'] ?? ''))) === $key) {
400	                return trim((string) ($attr['value'] ?? ''));
401	            }
402	        }
403	
404	        return '';
405	    }
406	
407	    /**
408	     * Resolve the commission rate for a line item, server-side. Precedence:
409	     *   1. product metafield `sidest.commission_override` (brand-set per-product)
410	     *   2. brand.brand_store_settings.default_commission_rate (brand default)
411	     *   3. config('sidest.store.default_commission_rate', 15) (platform fallback)
412	     *
413	     * @param  array<string, float|null>  $overrideMap
414	     * @return array{0: float, 1: string} [rate, rate_source]
415	     */
416	    private function resolveCommissionRate(
417	        string $productGid,
418	        array $overrideMap,
419	        ?BrandStoreSettings $brandSettings,
420	        float $platformDefault,
421	    ): array {
422	        if ($productGid !== '' && isset($overrideMap[$productGid]) && $overrideMap[$productGid] !== null) {
423	            $rate = (float) $overrideMap[$productGid];
424	            if ($rate > 0 && $rate <= 100) {
425	                return [$rate, 'metafield_override'];
426	            }
427	        }
428	
429	        if ($brandSettings && $brandSettings->default_commission_rate !== null) {
430	            return [(float) $brandSettings->default_commission_rate, 'brand_default'];
431	        }
432	
433	        return [$platformDefault, 'platform_default'];
434	    }
435	
436	    /**
437	     * Pull the buyer-submitted sidest_commission_rate for the audit trail.
438	     * NOT used for calculation — returned verbatim so post-hoc analysis can
439	     * spot cart tampering or Hydrogen/webhook drift.
440	     */
441	    private function extractSubmittedRate(array $lineItem): ?string
442	    {
443	        $properties = Arr::get($lineItem, 'properties', []);
444	        if (! is_array($properties)) {
445	            return null;
446	        }
447	        foreach ($properties as $prop) {
448	            if (is_array($prop) && strtolower(trim((string) ($prop['name'] ?? ''))) === 'sidest_commission_rate') {
449	                return (string) ($prop['value'] ?? '');
450	            }
451	        }
452	
453	        return null;
454	    }
455	}
