3	namespace App\Jobs\Notifications;
4	
5	use App\Services\Notifications\NotificationPublisher;
6	use Illuminate\Bus\Queueable;
7	use Illuminate\Contracts\Queue\ShouldQueue;
8	use Illuminate\Foundation\Bus\Dispatchable;
9	use Illuminate\Queue\InteractsWithQueue;
10	use Illuminate\Queue\SerializesModels;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	
14	// V2: Weekly sales/commission rollup notification for all active professionals. Runs on scheduled cron.
15	class SendWeeklyAnalyticsNotificationJob implements ShouldQueue
16	{
17	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
18	
19	    public int $tries = 1;
20	
21	    public int $timeout = 300;
22	
23	    public function __construct()
24	    {
25	        $this->onQueue('notifications');
26	    }
27	
28	    public function handle(NotificationPublisher $publisher): void
29	    {
30	        $yearWeek = now()->format('o-W'); // ISO year + week number
31	        $weekStart = now()->subDays(7)->toDateString();
32	        $weekEnd = now()->subDay()->toDateString();
33	
34	        DB::table('core.professionals')
35	            ->where('status', 'active')
36	            ->whereNull('deleted_at')
37	            ->orderBy('id')
38	            ->chunkById(200, function ($professionals) use ($publisher, $yearWeek, $weekStart, $weekEnd): void {
39	                $ids = $professionals->pluck('id')->all();
40	
41	                $metricsByPro = DB::table('analytics.professional_metrics_daily')
42	                    ->whereIn('affiliate_professional_id', $ids)
43	                    ->whereBetween('day', [$weekStart, $weekEnd])
44	                    ->select('affiliate_professional_id')
45	                    ->selectRaw('COALESCE(SUM(orders_count), ?) as orders', [0])
46	                    ->selectRaw('COALESCE(SUM(commission_accrued_cents), ?) as commission_cents', [0])
47	                    ->groupBy('affiliate_professional_id')
48	                    ->get()
49	                    ->keyBy('affiliate_professional_id');
50	
51	                foreach ($professionals as $professional) {
52	                    try {
53	                        $metrics = $metricsByPro->get($professional->id);
54	                        $this->notifyProfessional($publisher, $professional, $metrics, $yearWeek);
55	                    } catch (\Throwable $e) {
56	                        Log::warning('Weekly analytics notification failed', [
57	                            'professional_id' => $professional->id,
58	                            'message' => $e->getMessage(),
59	                        ]);
60	                    }
61	                }
62	            });
63	    }
64	
65	    private function notifyProfessional(
66	        NotificationPublisher $publisher,
67	        object $professional,
68	        ?object $metrics,
69	        string $yearWeek,
70	    ): void {
71	        $orders = (int) ($metrics?->orders ?? 0);
72	        $commissionCents = (int) ($metrics?->commission_cents ?? 0);
73	
74	        if ($orders === 0 && $commissionCents === 0) {
75	            return;
76	        }
77	
78	        $body = "Last 7 days: {$orders} sale".($orders !== 1 ? 's' : '');
79	        if ($commissionCents > 0) {
80	            $commission = 'A$'.number_format($commissionCents / 100, 2);
81	            $body .= ", {$commission} in commissions";
82	        }
83	        $body .= '.';
84	
85	        $publisher->publish(
86	            professionalId: $professional->id,
87	            frontendType: 'Info',
88	            category: 'analytics_weekly',
89	            title: 'Your weekly analytics',
90	            body: $body,
91	            dedupeKey: "analytics.weekly.{$professional->id}.{$yearWeek}",
92	            ctaUrl: '/account/store?section=analytics',
93	            retentionConfigKey: 'analytics_weekly',
94	        );
95	    }
96	}
